package edu.synergy.algorithms.hash;
import java.util.*;
public final class HashAlgorithms { private final Map<String,List<Integer>> students=new HashMap<>(); public void addStudent(String name){students.putIfAbsent(name,new ArrayList<>());} public void addGrade(String name,int grade){if(grade<0||grade>100)throw new IllegalArgumentException("grade must be 0..100");students.computeIfAbsent(name,k->new ArrayList<>()).add(grade);} public double getAverageGrade(String name){List<Integer>g=students.get(name);if(g==null||g.isEmpty())return 0;long s=0;for(int v:g)s+=v;return (double)s/g.size();} public static Map<Integer,Integer> frequencies(int[]values){Map<Integer,Integer>m=new LinkedHashMap<>();for(int v:values)m.merge(v,1,Integer::sum);return m;} public static double averageUntilZero(Scanner scanner){long sum=0;int count=0;while(scanner.hasNextInt()){int v=scanner.nextInt();if(v==0)break;sum+=v;count++;}return count==0?0:(double)sum/count;} }
